#!/bin/bash


export $(grep -v '^#' ./conf.env | sed 's/\r$//' | xargs)
OPENSTACKKEYCLOAK_PATH="./rawdata_zone/openstackKeycloak"
OPENSTACKKEYCLOAK_KUBE_PATH="./kubernetes/rawdata_zone/openstackKeycloak"

if [ -z "$KEYCLOAK_ADMIN" ]; then
  echo "Set the Keycloak admin username in conf.env file."
  exit 1
fi

if [ -z "$KEYCLOAK_ADMIN_PASSWORD" ]; then
  echo "Set the Keycloak admin password in conf.env file."
  exit 1
fi

if [ -z "$KEYCLOAK_PUBLIC_URL" ]; then
  echo "Set the Keycloak public URL in conf.env file."
  exit 1
fi

# The realm is generated by the root create_conf.sh (same file as docker-compose)
if [ ! -f "$OPENSTACKKEYCLOAK_PATH/realm/datalake-realm.json" ]; then
  echo "$OPENSTACKKEYCLOAK_PATH/realm/datalake-realm.json not found : run the root create_conf.sh first."
  exit 1
fi

mkdir -p $OPENSTACKKEYCLOAK_KUBE_PATH/volumes


###################################
# KEYCLOAK REALM
###################################
# Imported at start (--import-realm), only if the realm does not exist yet : users created later are kept.
# Secret : it holds the client secret and the sample user password.
cat << EOF > $OPENSTACKKEYCLOAK_KUBE_PATH/volumes/secret_keycloak_realm.yml
apiVersion: v1
kind: Secret
metadata:
  name: keycloak-realm
  namespace: datalake
  labels:
    app.kubernetes.io/name: keycloak
    app.kubernetes.io/part-of: security-zone
type: Opaque
stringData:
  datalake-realm.json: |
$(sed -e 's/\r$//' -e 's/^/    /' $OPENSTACKKEYCLOAK_PATH/realm/datalake-realm.json)
EOF
chmod 600 $OPENSTACKKEYCLOAK_KUBE_PATH/volumes/secret_keycloak_realm.yml


###################################
# KEYCLOAK ENVIRONMENT
###################################
# Same variables as the keycloak service of create_docker.sh
cat << EOF > $OPENSTACKKEYCLOAK_KUBE_PATH/volumes/configmap_keycloak_env.yml
apiVersion: v1
kind: ConfigMap
metadata:
  name: keycloak-env
  namespace: datalake
  labels:
    app.kubernetes.io/name: keycloak
    app.kubernetes.io/part-of: security-zone
data:
  KC_HTTP_ENABLED: "true"
  KC_HOSTNAME: "$KEYCLOAK_PUBLIC_URL"
  KC_HOSTNAME_STRICT: "false"
  KC_HOSTNAME_BACKCHANNEL_DYNAMIC: "true"
  KC_HEALTH_ENABLED: "true"
EOF

cat << EOF > $OPENSTACKKEYCLOAK_KUBE_PATH/volumes/secret_keycloak_env.yml
apiVersion: v1
kind: Secret
metadata:
  name: keycloak-env
  namespace: datalake
  labels:
    app.kubernetes.io/name: keycloak
    app.kubernetes.io/part-of: security-zone
type: Opaque
stringData:
  KC_BOOTSTRAP_ADMIN_USERNAME: "$KEYCLOAK_ADMIN"
  KC_BOOTSTRAP_ADMIN_PASSWORD: "$KEYCLOAK_ADMIN_PASSWORD"
EOF
chmod 600 $OPENSTACKKEYCLOAK_KUBE_PATH/volumes/secret_keycloak_env.yml
